import { motion, AnimatePresence } from 'motion/react';
import { Home, Keyboard, Activity, Dumbbell, User } from 'lucide-react';
import { useNavigate, useLocation } from 'react-router-dom';

const tabs = [
  { label: '首页', Icon: Home, path: '/' },
  { label: '键盘', Icon: Keyboard, path: '/ai' },
  { label: '诊断', Icon: Activity, path: '/real' },
  { label: '训练', Icon: Dumbbell, path: '/train' },
  { label: '我的', Icon: User, path: '/profile' },
];

export function HomeTabBar() {
  const navigate = useNavigate();
  const location = useLocation();

  const activeIndex = tabs.findIndex((t) => t.path === location.pathname);
  const active = activeIndex === -1 ? 0 : activeIndex;

  return (
    <div
      className="relative flex-shrink-0 pb-safe"
      style={{
        background: '#FFFFFF',
        borderTop: '1px solid rgba(0,0,0,0.05)',
        boxShadow: '0 -8px 24px rgba(0,0,0,0.04)',
        borderTopLeftRadius: '24px',
        borderTopRightRadius: '24px'
      }}
    >
      <div className="flex items-center justify-around px-2" style={{ height: 72 }}>
        {tabs.map((tab, index) => {
          const { Icon, label, path } = tab;
          const isActive = active === index;

          return (
            <button
              key={label}
              onClick={() => navigate(path)}
              className="relative flex flex-col items-center justify-center gap-1"
              style={{ minWidth: 64, height: '100%' }}
            >
              <motion.div
                className="relative flex items-center justify-center rounded-2xl"
                style={{ 
                  width: isActive ? 48 : 36, 
                  height: isActive ? 36 : 36, 
                  background: isActive ? '#10B981' : 'transparent',
                  transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)'
                }}
                whileTap={{ scale: 0.9 }}
              >
                <Icon
                  size={isActive ? 20 : 24}
                  color={isActive ? '#FFFFFF' : '#9CA3AF'}
                  strokeWidth={isActive ? 3 : 2.5}
                />
              </motion.div>

              <span
                style={{
                  color: isActive ? '#111827' : '#9CA3AF',
                  fontSize: '11px',
                  fontWeight: isActive ? 700 : 600,
                  lineHeight: 1,
                  marginTop: '2px'
                }}
              >
                {label}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}
